import json, html
from pathlib import Path
ROOT=Path(__file__).parent
OUT=ROOT/'public'; OUT.mkdir(exist_ok=True)
data=json.loads((ROOT/'content.json').read_text())
person=data['person']; ventures=data['ventures']; experience=data['experience']
nav='<a class="wordmark" href="/" aria-label="Vafa.co home">VAFA<span> / </span>CO</a><nav aria-label="Main navigation"><a href="/#about">About</a><a href="/#ventures">Ventures</a><a href="/experience/">Experience</a><a href="/#contact">Connect <span aria-hidden="true">↗</span></a></nav>'
def page(title,body,path='/',description='The personal headquarters of Emod Vafa. Growth leadership, independent ventures, and systems built for long-term value.'):
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+'</title><meta name="description" content="'+html.escape(description)+'"><link rel="canonical" href="https://vafa.co'+path+'"><meta property="og:title" content="'+html.escape(title)+'"><meta property="og:description" content="'+html.escape(description)+'"><meta property="og:type" content="website"><meta property="og:url" content="https://vafa.co'+path+'"><meta name="theme-color" content="#f4f1e9"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css"><script type="application/ld+json">'+json.dumps(person)+'</script></head><body><a class="skip" href="#main">Skip to content</a><header class="wrap">'+nav+'</header><main id="main">'+body+'</main><footer class="wrap"><a class="wordmark" href="/">VAFA<span> / </span>CO</a><p>The personal headquarters of Emod Vafa.</p><div><a href="/identity.json">Public identity</a><a href="/privacy/">Privacy</a><span>© 2026 Emod Vafa</span></div></footer></body></html>'
def write(path,title,body):
 dest=OUT/path/'index.html'; dest.parent.mkdir(parents=True,exist_ok=True); dest.write_text(page(title,body,'/'+str(path).strip('/')+'/'))
def rows():
 return ''.join('<a class="venture" href="/ventures/'+v['slug']+'/"><span class="ordinal">0'+str(i+1)+'</span><div><p class="eyebrow">'+v['category']+'</p><h3>'+v['name']+'</h3><p>'+v['text']+'</p></div><span class="venture-meta">'+v['role']+'<br><small>'+v['status']+'</small></span><span class="arrow" aria-hidden="true">↗</span></a>' for i,v in enumerate(ventures))
body='''<section class="hero wrap"><div class="hero-top"><p class="eyebrow">Emod Vafa</p><p class="eyebrow location">Toronto, Canada · Working globally</p></div><h1>Build with intent.<br>Grow with <em>discipline.</em></h1><div class="hero-bottom"><p class="intro">Growth executive. Entrepreneur. Systems thinker.<br>I connect strategy, marketing, and technology to build businesses with lasting value.</p><a class="text-link" href="#ventures">Explore the work <span aria-hidden="true">↘</span></a></div><div class="hero-seal" aria-hidden="true">V<span>Independent thinking. Enduring value.</span></div></section>
<section id="about" class="wrap about"><p class="eyebrow">01 / Perspective</p><div><h2>Growth is a discipline.<br><em>Value is the objective.</em></h2><p>I work at the intersection of customer acquisition, business strategy, and technology. My focus is turning ambition into systems that can be measured, improved, and built upon.</p><p>Over more than 15 years, that work has taken me across technology, legal services, automotive, real estate, and commerce — from leading marketing teams to building independent ventures.</p><a class="text-link" href="/experience/">Selected experience <span aria-hidden="true">↗</span></a></div></section>
<section id="ventures" class="dark"><div class="wrap"><div class="section-heading"><p class="eyebrow">02 / Ventures</p><h2>Independent ventures.<br><em>A shared way of thinking.</em></h2></div>'''+rows()+'''<div class="infrastructure"><p class="eyebrow">Behind the work</p><p><strong>Venture Launch OS</strong> — reusable internal systems for developing and testing digital ventures.</p></div></div></section>
<section class="wrap practice"><p class="eyebrow">03 / Practice</p><h2>From first principles<br>to <em>practical outcomes.</em></h2><div class="practice-grid"><article><span>01</span><h3>Revenue systems</h3><p>Connect demand generation, conversion, and retention around the economics of the business.</p></article><article><span>02</span><h3>Intelligent operations</h3><p>Use technology and automation to reduce friction and make good work repeatable.</p></article><article><span>03</span><h3>Enduring assets</h3><p>Build brands, capabilities, and digital properties that become more valuable over time.</p></article></div></section>
<section id="contact" class="contact"><div class="wrap"><p class="eyebrow">04 / Connect</p><h2>The right conversation<br>can change <em>what comes next.</em></h2><p>For leadership opportunities, business growth, and thoughtful collaborations.</p><a class="email" href="mailto:Emod@Vafa.co">Emod@Vafa.co <span aria-hidden="true">↗</span></a><div class="contact-links"><a href="https://cal.com/emodvafa">Book a conversation ↗</a><a href="https://ca.linkedin.com/in/emodvafa">LinkedIn ↗</a><a href="tel:+14164004699">416 400 4699</a></div></div></section>'''
(OUT/'index.html').write_text(page('Emod Vafa — Growth, Ventures & Enduring Value',body))
for v in ventures:
 write(Path('ventures')/v['slug'],v['name']+' — Emod Vafa','<section class="wrap detail"><a class="eyebrow" href="/#ventures">← All ventures</a><p class="eyebrow">'+v['category']+'</p><h1>'+v['name']+'</h1><p class="lead">'+v['text']+'</p><div class="detail-grid"><div><h2>Purpose</h2><p>'+v['detail']+'</p></div><dl><dt>My role</dt><dd>'+v['role']+'</dd><dt>Focus</dt><dd>'+v['status']+'</dd></dl></div><a class="text-link" href="'+v['url']+'">Visit official website ↗</a></section>')

def experience_page():
 entries=[dict(e,kind=e.get('kind', 'Career' if e['name'].startswith('Intercap') else 'Client work')) for e in experience]
 entries += [dict(name=v['name'], relationship=v['role']+' · '+v['status'],industry='Finance' if v['slug']=='canada-business-loan' else 'Technology',text=v['detail'],kind='Ventures',url='/ventures/'+v['slug']+'/') for v in ventures]
 cards=[]
 for i,e in enumerate(entries):
  name=html.escape(e['name']); category=html.escape(e['industry']); kind=html.escape(e['kind'])
  cards.append('<article class="brand-card" data-industry="'+category+'" data-kind="'+kind+'"><div class="brand-face"><span class="brand-number">0'+str(i+1)+'</span><h2>'+name+'</h2><span class="brand-category">'+category+'</span></div><div class="brand-body"><p class="eyebrow">'+kind+'</p><p class="brand-role">'+html.escape(e['relationship'])+'</p><details><summary>Explore the work <span aria-hidden="true">+</span></summary><p>'+html.escape(e['text'])+'</p>'+('<a class="text-link" href="'+e['url']+'">Venture profile ↗</a>' if 'url' in e else '')+'</details></div></article>')
 filters=''.join('<button type="button" data-filter="'+c+'" aria-pressed="'+('true' if c=='All' else 'false')+'">'+c+'</button>' for c in ['All','Legal','Automotive','Real Estate','Technology','Marketing','Finance','Commerce'])
 return '<section class="wrap experience-intro"><p class="eyebrow">Selected experience / Emod Vafa</p><h1>The businesses behind<br><em>the work.</em></h1><div class="experience-deck"><p>More than 15 years across industries. A consistent focus on customer acquisition, digital growth, and building revenue systems.</p><span>Leadership. Client work.<br>Independent ventures.</span></div></section><section class="wrap brand-collection" aria-labelledby="collection-title"><div class="collection-heading"><h2 id="collection-title">Selected businesses & teams</h2><p id="result-count" role="status" aria-live="polite">'+str(len(entries))+' selected profiles</p></div><div class="brand-filters" role="group" aria-label="Filter experience by industry">'+filters+'</div><div class="brand-grid">'+''.join(cards)+'</div><p id="empty-state" class="empty-state" hidden>Additional experience in this industry is being documented. <a href="mailto:Emod@Vafa.co?subject=Experience%20enquiry">Contact Emod for relevant background ↗</a></p><p class="editorial-note">Career roles, client engagements, and independent ventures are identified on each profile.</p></section><section class="experience-cta"><div class="wrap"><p class="eyebrow">The next chapter</p><h2>Experience is a starting point.<br><em>What matters is what comes next.</em></h2><a class="text-link" href="https://cal.com/emodvafa">Discuss a leadership role or collaboration ↗</a></div></section><script src="/experience.js" defer></script>'
write(Path('experience'),'Selected Experience — Emod Vafa',experience_page())
write(Path('privacy'),'Privacy — Vafa.co','<section class="wrap detail"><p class="eyebrow">Privacy · October 16, 2026</p><h1>A straightforward<br><em>approach to privacy.</em></h1><p>This site does not include advertising trackers, analytics scripts, cookies set by application code, or a contact database. The hosting provider may process technical request information to operate and secure the site.</p><p>Email and scheduling links open third-party services, which apply their own privacy policies. Information you choose to send by email is used to respond to your enquiry.</p><p>Questions: <a href="mailto:Emod@Vafa.co">Emod@Vafa.co</a>.</p></section>')
write(Path('404'),'Page Not Found — Vafa.co','<section class="wrap detail"><p class="eyebrow">404</p><h1>A different<br><em>direction.</em></h1><p>This page could not be found.</p><a class="text-link" href="/">Return home ↗</a></section>')
(OUT/'404.html').write_text((OUT/'404/index.html').read_text())
(OUT/'identity.json').write_text(json.dumps(person,indent=2)+'\n')
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://vafa.co/sitemap.xml\n')
urls=['/','/experience/','/privacy/']+['/ventures/'+v['slug']+'/' for v in ventures]
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>https://vafa.co'+u+'</loc></url>' for u in urls)+'</urlset>')
(OUT/'llms.txt').write_text('# Emod Vafa\n\nPersonal headquarters of Emod Vafa, growth marketing executive and entrepreneur.\n\n- Identity: https://vafa.co/identity.json\n- Experience: https://vafa.co/experience/\n- Ventures: https://vafa.co/#ventures\n- Contact: Emod@Vafa.co\n\nVafa.co represents a person, not a separate holding company. Client work is not evidence of ownership. Venture stages describe stated focus, not independently audited operating status.\n')
(OUT/'favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" fill="#191d1a"/><path d="M14 16L32 49 50 16M21 16L35 42" stroke="#c5b28b" stroke-width="2" fill="none"/></svg>')
print('Built',len(list(OUT.rglob('*.*'))),'public files')
